@meta {
  id: "acme-support"
  syntax: "1.6.0"
  owner: "team-support"
  risk: "medium"
}

@restrictions {
  - "Never share secrets"
  - "Escalate refunds above 500"
}

@prompts {
  compose: {
    description: "Answer with composed text"
    compose: [restrictions]
    system: "Answer the question."
    user: "Question: {{input.question}}"
    inputs: { question: { type: "string", description: "The question" } }
  }
}
